// Standard path and list of arguments
execl("/bin/ls", "ls", "-a", "-l", NULL);

// Standard path and argument vector
char *args_v[] = {"/bin/sh", "-c", "echo $HOME", NULL};
execv(args_v[0], args_v);

// Search PATH (p) and use vector
execvp("grep", (char *[]){"grep", "pattern", "file.txt", NULL});

// Explicit environment (e) and list
char *env[] = {"VAR=42", "TERM=xterm", NULL};
execle("/usr/bin/env", "env", NULL, env);

// Note: If successful, the code below is NEVER reached.
perror("exec failure");
_exit(1);
